# towers.py

class Tower:
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.damage = 10
        self.range = 100

    def draw(self, screen):
        pygame.draw.circle(screen, (0, 255, 0), (self.x, self.y), 20)

# enemies.py

import pygame

class Enemy:
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.health = 50
        self.speed = 1

    def move(self):
        self.x += self.speed

    def draw(self, screen):
        pygame.draw.rect(screen, (255, 0, 0), (self.x, self.y, 20, 20))

# stages.py

class Stage:
    def __init__(self):
        self.enemies = []

    def add_enemy(self, enemy):
        self.enemies.append(enemy)

    def update(self):
        for enemy in self.enemies:
            enemy.move()

    def draw(self, screen):
        for enemy in self.enemies:
            enemy.draw(screen)
